class Solution {
public:
    std::vector<int> cycleLengthQueries(int n, std::vector<std::vector<int>>& queries) {
        std::vector<int> ans;
        ans.reserve(queries.size());
        for (const auto& q : queries) {
            int a = q[0], b = q[1];
            int steps = 0;
            while (a != b) {
                if (a > b) a /= 2;
                else b /= 2;
                steps++;
            }
            ans.push_back(steps + 1);
        }
        return ans;
    }
};

class Solution {
    public int[] cycleLengthQueries(int n, int[][] queries) {
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int a = queries[i][0], b = queries[i][1];
            int steps = 0;
            while (a != b) {
                if (a > b) a /= 2;
                else b /= 2;
                steps++;
            }
            ans[i] = steps + 1;
        }
        return ans;
    }
}

var cycleLengthQueries = function(n, queries) {
    const ans = [];
    for (const [qa, qb] of queries) {
        let a = qa, b = qb;
        let steps = 0;
        while (a !== b) {
            if (a > b) a = Math.floor(a / 2);
            else b = Math.floor(b / 2);
            steps++;
        }
        ans.push(steps + 1);
    }
    return ans;
};
